// Compact workspace presentation; every figure uses the unchanged annual engine.
export function researchWorkspaceSummaryHTML(c,d,{identityError=null,startingDraft=null}={}){
 const details=researchResultsHTML(c,d,{identityError,region:'summary',startingDraft});
 if(identityError)return details;
 try{
  const r=calculateResearchOperating(d),timing=researchTimingResult(d,r),operating=timing.status==='incomplete'?r.enterprise:timing.enterprise;
  let bridge=null;try{if(timing.status!=='incomplete')bridge=calculateResearchBridge(d,timing.enterprise,{...(d.bridgeInputs||{}),calculationDate:timing.date});}catch(error){bridge={message:error.message};}
